<x-app-layout><x-slot name="header"><h1 class="text-xl font-bold">Issue Return Add</h1></x-slot><form method="POST" action="{{route('issue-returns.store')}}" x-data="ir()">@csrf<section class="rounded border bg-white p-6"><h2 class="border-b pb-3 text-lg">General Info</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><label>Issue Return date<input name="return_date" type="date" value="{{now()->format('Y-m-d')}}" class="mt-2 w-full rounded border"></label><label>Issue Return No<input readonly value="{{$nextNo}}" class="mt-2 w-full rounded border bg-slate-100"></label><label>Issue Return From<select name="returned_by_user_id" class="mt-2 w-full rounded border"><option value="">[Select]</option>@foreach($users as $u)<option value="{{$u->id}}">{{$u->name}}</option>@endforeach</select></label><label>Store<select name="store_id" x-model="store" required class="mt-2 w-full rounded border"><option value="">[Select]</option>@foreach($stores as $s)<option value="{{$s->id}}">{{$s->name}}</option>@endforeach</select></label><label class="md:col-span-2">Remarks<textarea name="remarks" class="mt-2 w-full rounded border"></textarea></label></div></section><section class="mt-5 overflow-hidden rounded border border-sky-200 bg-white"><div class="bg-sky-500 px-4 py-2 text-white">Details</div><table class="w-full text-sm"><thead class="bg-sky-50"><tr><th>Store Position</th><th>Item No</th><th>Item</th><th>Qty</th><th>ChesisNo</th><th></th></tr></thead><tbody><template x-for="(l,i) in lines"><tr class="border-t"><td><select :name="`items[${i}][store_position_id]`" class="w-full border"><option value="">Please Select</option><template x-for="p in positions.filter(x=>String(x.store_id)==String(store))"><option :value="p.id" x-text="p.name"></option></template></select></td><td><input x-model="l.part" @input="match(l)" :list="`ir-${i}`" class="w-full border"><datalist :id="`ir-${i}`"><template x-for="p in products"><option :value="p.part_no" x-text="`${p.part_no} — ${p.name}`"></option></template></datalist><input type="hidden" :name="`items[${i}][product_id]`" x-model="l.product"></td><td><input x-model="l.name" readonly class="w-full border bg-slate-50"></td><td><input x-model.number="l.qty" :name="`items[${i}][quantity]`" type="number" min=".01" step=".01" class="w-full border"></td><td><input x-model="l.chassis" :name="`items[${i}][chassis_no]`" class="w-full border"></td><td><button type="button" @click="del(i)" x-show="lines.length>1">×</button></td></tr></template></tbody></table><button type="button" @click="add" class="m-3 rounded bg-sky-100 px-3 py-2">+ Add row</button></section><div class="mt-5"><button class="rounded bg-[#1f7d88] px-5 py-2 text-white">Save</button></div></form><script>function ir(){return{products:@json($products),positions:@json($positions),store:'',lines:[{part:'',product:'',name:'',qty:0,chassis:''}],add(){this.lines.push({part:'',product:'',name:'',qty:0,chassis:''})},del(i){this.lines.splice(i,1)},match(l){let p=this.products.find(x=>x.part_no?.toLowerCase()===l.part.toLowerCase()||`${x.part_no} — ${x.name}`.toLowerCase()===l.part.toLowerCase());if(p)Object.assign(l,{part:p.part_no,product:p.id,name:p.name});else Object.assign(l,{product:'',name:''})}}}</script></x-app-layout>
